/**
 * @idol/goal-engine
 *
 * Deterministic Goal Engine & Stream Script Scheduler.
 *
 * Rules (from PLAN.md):
 * - Goals are explicit runtime objects.
 * - LLM never controls CTA frequency or goal intervals.
 * - Timing is deterministic; wording is generated by LLM.
 * - High-priority events (Jackpot, Donation) always interrupt/delay goals.
 * - Cooldowns and execution constraints are strictly enforced.
 */

import { z } from 'zod';
import type { GoalType, Priority, VisualState, Emotion } from '@idol/event-schema';

// ─────────────────────────────────────────────────────────
// 1. Goal Schema
// ─────────────────────────────────────────────────────────

export const GoalSchedule = z.object({
  minIntervalSeconds: z.number().int().positive().default(180),
  maxIntervalSeconds: z.number().int().positive().default(420),
});
export type GoalSchedule = z.infer<typeof GoalSchedule>;

export const GoalConstraints = z.object({
  doNotInterrupt: z.array(z.string()).default(['BIG_WIN', 'JACKPOT', 'DONATION', 'THANK_DONATION']),
  minStreamElapsedSeconds: z.number().int().default(0),
  requiresGameplayIdle: z.boolean().default(true),
});
export type GoalConstraints = z.infer<typeof GoalConstraints>;

export const GoalDefinition = z.object({
  id: z.string(),
  type: z.string(), // GoalType
  objective: z.string(),
  priority: z.union([
    z.literal(0), z.literal(1), z.literal(2), z.literal(3),
    z.literal(4), z.literal(5), z.literal(6), z.literal(7)
  ]).default(5), // P5 Default Scripted Goal
  schedule: GoalSchedule.default({ minIntervalSeconds: 180, maxIntervalSeconds: 420 }),
  constraints: GoalConstraints.default({
    doNotInterrupt: ['BIG_WIN', 'JACKPOT', 'DONATION', 'THANK_DONATION'],
    minStreamElapsedSeconds: 0,
    requiresGameplayIdle: true,
  }),
  visualStates: z.array(z.string()).default(['INVITE_PLAY', 'CTA']),
  tone: z.array(z.string()).default(['playful', 'friendly']),
  cooldownMs: z.number().int().nonnegative().default(120_000), // 2 min
  maxExecutionsPerStream: z.number().int().optional(),
  enabled: z.boolean().default(true),
});
export type GoalDefinition = z.infer<typeof GoalDefinition>;

export interface GoalRuntimeState {
  definition: GoalDefinition;
  executionCount: number;
  lastExecutedAt: number;
  nextEligibleAt: number;
}

// ─────────────────────────────────────────────────────────
// 2. Stream Script & Phases
// ─────────────────────────────────────────────────────────

