// ─────────────────────────────────────────────────────────
// 4. Stream Evaluation Context
// ─────────────────────────────────────────────────────────

export interface StreamContext {
  streamStartedAt: number;
  currentTime: number;
  currentVisualState: VisualState | string;
  isSpeaking: boolean;
  lastCtaAt: number;
  lastGoalAt: number;
  lastBigWinAt: number;
  chatVelocity: number; // messages per minute
  activeGoalId?: string | null | undefined;
}

// ─────────────────────────────────────────────────────────
// 5. Goal Engine Core
// ─────────────────────────────────────────────────────────

export class GoalEngine {
  private readonly _goals: Map<string, GoalRuntimeState> = new Map();
  private readonly _phases: StreamPhaseConfig[];
  private _streamStartedAt: number = 0;
  private _globalCtaCooldownMs: number = 90_000; // 90s minimum between any CTAs

  constructor(
    customGoals: GoalDefinition[] = DEFAULT_GOALS,
    customPhases: StreamPhaseConfig[] = DEFAULT_STREAM_PHASES
  ) {
    this._phases = customPhases;
    for (const def of customGoals) {
      this.registerGoal(def);
    }
  }

  startStream(timestamp: number = Date.now()): void {
    this._streamStartedAt = timestamp;
  }

  registerGoal(definition: GoalDefinition): void {
    const validated = GoalDefinition.parse(definition);
    this._goals.set(validated.id, {
      definition: validated,
      executionCount: 0,
      lastExecutedAt: 0,
      nextEligibleAt: 0,
    });
  }

  unregisterGoal(id: string): boolean {
    return this._goals.delete(id);
  }

  getGoal(id: string): GoalRuntimeState | undefined {
    return this._goals.get(id);
  }

  getAllGoals(): GoalRuntimeState[] {
    return Array.from(this._goals.values());
  }

  /**
   * Determine current stream phase based on elapsed minutes.
   */
  getCurrentPhase(currentTime: number = Date.now(), streamStartedAt?: number): StreamPhaseConfig {
    const started = streamStartedAt || (this._streamStartedAt > 0 ? this._streamStartedAt : currentTime);
    const elapsedMinutes = (currentTime - started) / 60_000;

    let cumulative = 0;
    for (const phase of this._phases) {
      cumulative += phase.durationMinutes;
      if (elapsedMinutes <= cumulative) {
        return phase;
      }
    }
    // Return closing phase if stream has run longer than total defined duration
    return this._phases[this._phases.length - 1]!;
  }

  /**
   * Evaluates all registered goals and returns the highest priority eligible goal if due.
   */
  evaluate(context: StreamContext): GoalDefinition | null {
    const now = context.currentTime || Date.now();
    const streamStart = context.streamStartedAt || (this._streamStartedAt > 0 ? this._streamStartedAt : now);
    const elapsedSeconds = (now - streamStart) / 1000;

    // Do not trigger goals while idol is already speaking
    if (context.isSpeaking) return null;

    // Do not trigger goals during high-energy states (Jackpot, Big Win, Thank Donation)
    const blockingStates = ['JACKPOT', 'BIG_WIN', 'THANK_DONATION', 'BOOT', 'AFK', 'RECOVERY'];
    if (blockingStates.includes(context.currentVisualState)) {
      return null;
    }

    const currentPhase = this.getCurrentPhase(now, streamStart);
    const eligibleGoals: { goal: GoalDefinition; score: number }[] = [];

    for (const state of this._goals.values()) {
      const def = state.definition;
      if (!def.enabled) continue;

      // Check max executions
      if (def.maxExecutionsPerStream && state.executionCount >= def.maxExecutionsPerStream) {
        continue;
      }

      // Check stream elapsed constraints
      if (elapsedSeconds < def.constraints.minStreamElapsedSeconds) {
        continue;
      }

      // Check phase compatibility
      const phaseAllows = currentPhase.allowedGoalTypes.includes(def.type) ||
                          currentPhase.allowedGoalTypes.includes('*');
      if (!phaseAllows) continue;

      // Check goal-specific cooldown
      if (state.lastExecutedAt > 0 && (now - state.lastExecutedAt) < def.cooldownMs) {
        continue;
      }

      // Global CTA throttle if goal is CTA / INVITE
      if ((def.type === 'CTA' || def.type === 'INVITE_PLAY') &&
          (now - context.lastCtaAt) < this._globalCtaCooldownMs) {
        continue;
      }

      // Time since last execution
      const timeSinceExecutionSec = state.lastExecutedAt === 0
        ? elapsedSeconds
        : (now - state.lastExecutedAt) / 1000;

      // If scheduled interval elapsed
      if (timeSinceExecutionSec >= def.schedule.minIntervalSeconds) {
        // Score based on urgency and priority (lower priority number = higher weight)
        const priorityWeight = (10 - def.priority) * 10;
        const overdueFactor = Math.min(2.0, timeSinceExecutionSec / def.schedule.maxIntervalSeconds);
        const score = priorityWeight * overdueFactor;

        eligibleGoals.push({ goal: def, score });
      }
    }

    if (eligibleGoals.length === 0) return null;

    // Sort by highest score
    eligibleGoals.sort((a, b) => b.score - a.score);
    return eligibleGoals[0]!.goal;
  }

  /**
   * Record that a goal was executed.
   */
  recordExecution(goalId: string, timestamp: number = Date.now()): void {
    const goalState = this._goals.get(goalId);
    if (goalState) {
      goalState.executionCount += 1;
      goalState.lastExecutedAt = timestamp;
      // Schedule next eligible timestamp
      const intervalMs = goalState.definition.schedule.minIntervalSeconds * 1000;
      goalState.nextEligibleAt = timestamp + intervalMs;
    }
  }

  /**
   * Reset all execution counts (e.g. for new stream session).
   */
  reset(): void {
    this._streamStartedAt = Date.now();
    for (const state of this._goals.values()) {
      state.executionCount = 0;
      state.lastExecutedAt = 0;
      state.nextEligibleAt = 0;
    }
  }
}
